// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

// Uncomment this line to use console.log
// import "hardhat/console.sol";

contract Lock {
    uint public unlockTime;
    address payable public owner;

    event Withdrawal(uint amount, uint when);

    constructor(uint _unlockTime) payable {
        require(
            block.timestamp < _unlockTime,
            "Unlock time should be in the future"
        );

        unlockTime = _unlockTime;
        owner = payable(msg.sender);
    }

    function withdraw() public {
        // Uncomment this line, and the import of "hardhat/console.sol", to print a log in your terminal
        // console.log("Unlock time is %o and block timestamp is %o", unlockTime, block.timestamp);

        require(block.timestamp >= unlockTime, "You can't withdraw yet");
        require(msg.sender == owner, "You aren't the owner");

        emit Withdrawal(address(this).balance, block.timestamp);

        owner.transfer(address(this).balance);
    }
}

contracts/WulaPal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract WulaPal {
    struct Member {
        address wallet;
        uint256 contribution;
        bool hasWithdrawn;
    }

    address public admin;
    Member[] public members;
    uint256 public totalContributions;
    uint256 public payoutIndex;
    
    event ContributionReceived(address indexed member, uint256 amount);
    event PayoutDistributed(address indexed recipient, uint256 amount);

    constructor() {
        admin = msg.sender;
    }

    function joinPaluwagan() external payable {
        require(msg.value > 0, "Contribution required");
        members.push(Member(msg.sender, msg.value, false));
        totalContributions += msg.value;
        emit ContributionReceived(msg.sender, msg.value);
    }

    function distributePayout() external {
        require(msg.sender == admin, "Only admin can distribute");
        require(payoutIndex < members.length, "All payouts completed");

        Member storage recipient = members[payoutIndex];
        require(!recipient.hasWithdrawn, "Already withdrawn");

        payable(recipient.wallet).transfer(totalContributions);
        recipient.hasWithdrawn = true;

        emit PayoutDistributed(recipient.wallet, totalContributions);
        
        payoutIndex++;
    }

    function getTransactionHistory() external view returns (Member[] memory) {
        return members;
    }
}

